<?php
$search=scalar_value($_GET,'search');$editing=isset($_GET['edit'])?one("SELECT * FROM users WHERE id=? AND role='customer'",[(int)$_GET['edit']]):null;
$customers=all("SELECT * FROM users WHERE role='customer'".($search!==''?' AND (name LIKE ? OR email LIKE ?)':'').' ORDER BY id DESC',$search!==''?['%'.$search.'%','%'.$search.'%']:[]);
feature_search_form('customers','Customer name or email');
?>
<div class="admin-split"><section class="admin-card"><h2>Customers</h2><div class="table-wrap"><table><thead><tr><th>Name / email</th><th>Phone</th><th>Status</th><th>Actions</th></tr></thead><tbody>
<?php foreach($customers as $c):?><tr><td><?=e($c['name'])?><small><?=e($c['email'])?></small></td><td><?=e($c['phone'])?></td><td><?=$c['active']?'Active':'Inactive'?></td><td><a href="<?=e(url('admin',['section'=>'customers','edit'=>$c['id']]))?>">Profile / orders</a><?php delete_form('admin_customer_delete','customers',(int)$c['id']);?></td></tr><?php endforeach;?><?php if(!$customers):?><tr><td colspan="4">No customers found.</td></tr><?php endif;?></tbody></table></div></section>
<section class="admin-card"><h2><?=$editing?'Edit customer':'Add customer'?></h2><form method="post" class="form-grid"><?php admin_hidden('admin_customer_save','customers',(int)($editing['id']??0));afield('name','Name',$editing['name']??'');afield('email','Email',$editing['email']??'','email');afield('phone','Phone',$editing['phone']??'','text',false);if(!$editing)afield('password','Initial password (8–72 characters)','','password');acheck('active','Account active',(bool)($editing['active']??true));?><button class="btn">Save customer</button></form><p>Customers with orders cannot be deleted. Deactivate their account to retain history.</p>
<?php if($editing):?><h3>Order history</h3><?php $history=all('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC',[$editing['id']]);if(!$history):?><p>No orders.</p><?php endif;foreach($history as $o):?><p><a href="<?=e(url('admin',['section'=>'orders','view'=>$o['id']]))?>"><?=e($o['reference'])?></a> · <?=e($o['status'])?> · <?=money($o['total'])?></p><?php endforeach;?><h3>Saved addresses</h3><?php foreach(all('SELECT * FROM addresses WHERE user_id=?',[$editing['id']]) as $a):?><p><?=e($a['label'].' · '.address_snapshot($a))?></p><?php endforeach;?><a href="<?=e(url('admin',['section'=>'customers']))?>">Add another customer</a><?php endif;?></section></div>
